import {RECORD_FILE_LIMIT,RECORD_STORAGE_KEY,createRecordBackup,parseRecordBackup,blankRecordData,recordMessages,recordsDialog,recordImportDialog,recordDeleteDialog} from './records.mjs';
import {careerMessages,careerDirections,evidenceSources,roleEvidenceDialog,dosmDialog} from './career-ui.mjs';
import {fetchArxivSnapshot} from './rss.mjs';
import {skills,roles,presets,market,matchRoles,resources} from './model.mjs';
import {messages} from './i18n.js';
import {journeyMessages} from './journey-i18n.mjs';
import {buildWeeklyPlan,reflectSkill,learningExercises} from './journey.mjs';
import {entryHeader,welcomeScreen,authScreen,setupScreen,onboardingGuide,executionPanel,reflectionPanel,pricingStory,upgradePreview} from './experience.mjs';
import {discoveryMessages} from './discovery-i18n.mjs';
import {suggestSkills} from './discovery-model.mjs';
import {cleanWorkDetails,transitionStrategy} from './work-context.mjs';
import {discoveryHeader,discoveryFooter,discoveryProgress,discoveryLanding,sampleJourney,profileIntake,strengthReport,directionList,selectedPath,compactPricing,compactAuth} from './discovery.mjs';
Object.assign(messages,journeyMessages,discoveryMessages,careerMessages,recordMessages);

const root=document.querySelector('#app');
const modalRoot=document.querySelector('#modal-root');
const validViews=['welcome','auth','setup','sample','opportunities','explore','pathway','signals','saved','pricing','about'];
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
const stored=read(RECORD_STORAGE_KEY,{});
const cleanProfile=p=>({name:String(p?.name||'Alex Tan').slice(0,40),experience:String(p?.experience||'').slice(0,1500),hoursConfirmed:p?.hoursConfirmed===true,role:Array.isArray(p?.role)?p.role:String(p?.role||'Operations & Marketing Lead').slice(0,100),years:Math.max(0,Math.min(45,Number(p?.years)||0)),hours:Math.max(1,Math.min(40,Number(p?.hours)||6)),budget:p?.budget==='low'?'low':'free',skills:Array.isArray(p?.skills)?p.skills.filter(x=>Object.hasOwn(skills,x)):[],...cleanWorkDetails(p)});
const state={theme:stored.theme==='light'?'light':'dark',directionFamily:'all',directionSort:'fit',directionPage:0,directionFocus:null,lang:['zh','en','ms'].includes(stored.lang)?stored.lang:'zh',view:stored.discoveryVersion===3&&validViews.includes(location.hash.slice(1))?location.hash.slice(1):'welcome',audience:['transition','employed','returning'].includes(stored.audience)?stored.audience:'transition',profile:cleanProfile(stored.profile||presets.transition),scenario:stored.scenario==='fast'?'fast':'moderate',saved:Array.isArray(stored.saved)?stored.saved.filter(x=>roles.some(r=>r.id===x)):[],target:roles.some(r=>r.id===stored.target)?stored.target:'analyst',pro:stored.pro===true,billing:'monthly',quarter:1,progress:stored.progress&&typeof stored.progress==='object'?stored.progress:{},discoveryVersion:3,isSample:stored.discoveryVersion===3?stored.isSample===true:true,demoProfile:cleanProfile(stored.demoProfile||presets.transition),demoPlans:{},demoWeekly:{},demoReflections:[],planReady:stored.planReady&&typeof stored.planReady==='object'?stored.planReady:{},goalChosen:stored.discoveryVersion===3&&stored.goalChosen===true,profileConfirmed:stored.profileConfirmed===true||stored.sessionReady===true,sessionReady:stored.sessionReady===true,onboardingComplete:stored.onboardingComplete===true,welcomeStep:0,authMode:'signin',setupStep:0,startDestination:'explore',executionPlans:stored.executionPlans&&typeof stored.executionPlans==='object'?stored.executionPlans:{},weeklyProgress:stored.weeklyProgress&&typeof stored.weeklyProgress==='object'?stored.weeklyProgress:{},reflections:Array.isArray(stored.reflections)?stored.reflections.filter(r=>Object.hasOwn(skills,r.skillId)&&roles.some(x=>x.id===r.roleId)):[],research:null,researchStatus:'cached',researchError:false,refreshing:false};
if(stored.discoveryVersion!==3)history.replaceState(null,'','#welcome');
const langIndex=()=>['zh','en','ms'].indexOf(state.lang);
const t=key=>messages[key]?.[langIndex()]??key;
const local=v=>Array.isArray(v)?v[langIndex()]:v;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={archive:'M4 4h16v4H4Z M5 8v13h14V8 M9 12h6',upload:'M12 16V3 m-5 5 5-5 5 5 M4 16v5h16v-5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',sun:'M12 3v2 M12 19v2 M3 12h2 M19 12h2 M5.6 5.6 1.4 1.4 M17 17l1.4 1.4 M5.6 18.4 1.4-1.4 M17 7l1.4-1.4 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',moon:'M20.8 13.2A9 9 0 0 1 10.8 3.2 9 9 0 1 0 20.8 13.2Z',home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',compass:'M16.5 7.5 14 14l-6.5 2.5L10 10Z M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',path:'M5 4v12a4 4 0 0 0 4 4h6a4 4 0 0 0 0-8h-4a4 4 0 0 1 0-8h7 M3 4h4 M16 2l3 2-3 2',radar:'M12 3a9 9 0 1 0 9 9 M12 7a5 5 0 1 0 5 5 M12 12l8-8 M17 3h4v4',bookmark:'M6 3h12v18l-6-4-6 4Z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',arrow:'M4 12h15 M14 6l6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M3 12h18 M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z',pin:'M18 9c0 5-6 11-6 11S6 14 6 9a6 6 0 0 1 12 0Z M14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',edit:'m15 4 5 5-11 11H4v-5Z M13 6l5 5',layers:'m12 3 9 5-9 5-9-5Z M3 12l9 5 9-5 M3 16l9 5 9-5',chart:'M4 3v17h17 M8 15l4-5 4 2 5-7',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z M13 12a1 1 0 1 1-2 0 1 1 0 0 1 2 0Z',check:'m5 12 4 4L19 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M12 7v5l3 2',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M12 11v6 M12 7h.01',book:'M3 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H3Z M21 4h-6a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h5Z',leaf:'M20 3C8 2 3 8 5 15c5 9 17 1 15-12Z M5 20 16 9',external:'M14 3h7v7 M21 3 10 14 M10 3H4v17h17v-6',up:'m5 16 6-6 4 3 6-8 M16 5h5v5',close:'m6 6 12 12 M6 18 18 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',compare:'M8 3v18 M16 3v18 M3 7h10 M11 17h10',menu:'M4 6h16 M4 12h16 M4 18h16',briefcase:'M4 7h16v14H4Z M8 7V3h8v4 M4 12h16 M10 12v3h4v-3',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z',refresh:'M20 11a8 8 0 0 0-14-5L3 9 M3 3v6h6 M4 13a8 8 0 0 0 14 5l3-3 M15 15h6v6',lock:'M6 10h12v11H6Z M8 10V6a4 4 0 0 1 8 0v4'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const brandMark=()=>'<span class="brand-mark"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M8 25V8h8a5.5 5.5 0 0 1 0 11h-3" stroke="#F3F8FE" stroke-width="3" stroke-linecap="round"/><path d="m17 18 8 7m-4-9h5v5" stroke="#BFD1FF" stroke-width="2.7" stroke-linecap="round" stroke-linejoin="round"/></svg></span>';
const activeProfile=()=>state.isSample?state.demoProfile:state.profile;
const profileRole=()=>local(activeProfile().role);
const skillName=id=>local(skills[id]);
const ranking=()=>matchRoles(activeProfile(),state.scenario);
const targetRole=()=>ranking().find(r=>r.id===state.target)||ranking()[0];
const recordStateSnapshot=()=>({theme:state.theme,lang:state.lang,audience:state.audience,profile:state.profile,scenario:state.scenario,saved:state.saved,target:state.target,pro:state.pro,progress:state.pro?state.progress:{},sessionReady:state.sessionReady,onboardingComplete:state.onboardingComplete,executionPlans:state.executionPlans,weeklyProgress:state.pro?state.weeklyProgress:{},reflections:state.pro?state.reflections:[],discoveryVersion:3,isSample:state.isSample,demoProfile:state.demoProfile,planReady:state.planReady,goalChosen:state.goalChosen,profileConfirmed:state.profileConfirmed});
const persist=()=>write(RECORD_STORAGE_KEY,recordStateSnapshot());
const button=(text,action,kind='small-button',ico='arrow',extra='')=>`<button class="${kind}" data-action="${action}" ${extra}>${esc(text)}${ico?icon(ico):''}</button>`;
const sourceLink=(url,label)=>`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('external')}</a>`;
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3400)}
function navigate(view){if(!validViews.includes(view))return;if(view==='pathway'&&!state.goalChosen)view='opportunities';closeModal();state.view=view;location.hash=view;render();window.scrollTo({top:0,behavior:'instant'})}
function navigation(){return `<aside class="sidebar" aria-label="${t('workspace')}"><a class="brand" href="#explore" aria-label="RePath AI">${brandMark()}<span>RePath</span><span class="brand-ai">AI</span></a><div class="brand-caption">${t('tagline')}</div><div class="nav-label">${t('personal')}</div><nav class="nav-group">${[['explore','compass','overview'],['pathway','path','pathway'],['signals','radar','signals'],['saved','bookmark','saved']].map(([view,ico,key])=>`<button class="nav-item ${state.view===view?'active':''}" data-view="${view}" aria-label="${t(key)}" ${state.view===view?'aria-current="page"':''}>${icon(ico)}<span>${t(key)}</span>${view==='saved'&&state.saved.length?`<span class="count">${state.saved.length}</span>`:''}</button>`).join('')}</nav><div class="nav-divider"></div><div class="nav-label">${t('tools')}</div><nav class="nav-group">${[['pricing','spark','plans'],['about','info','help']].map(([view,ico,key])=>`<button class="nav-item ${state.view===view?'active':''}" data-view="${view}" aria-label="${t(key)}" ${state.view===view?'aria-current="page"':''}>${icon(ico)}<span>${t(key)}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="upgrade-card">${icon('spark')}<h4>${t(state.pro?'proActive':'pro')}</h4><p>${t('proDesc')}</p>${button(t('upgrade'),'pricing','', 'arrow')}</div><button class="sidebar-user" data-action="profile"><span class="avatar">AT</span><span><strong>${esc(state.profile.name)}</strong><small>${t(state.pro?'proActive':'free')}</small></span>${icon('down')}</button></div></aside><div class="mobile-overlay" data-action="menu"></div>`}
function topbar(){const title=t({explore:'overview',pathway:'pathway',signals:'signals',saved:'saved',pricing:'plans',about:'help'}[state.view]);return `<header class="topbar"><button class="menu-button" data-action="menu" aria-label="Menu">${icon('menu')}</button><a class="mobile-brand" href="#explore">${brandMark()}RePath<span class="brand-ai">AI</span></a><div class="breadcrumbs">${t('workspace')}${icon('chevron')}<strong>${title}</strong></div><div class="top-actions"><button class="top-tour-link" data-action="intro-home">${icon('info')}${t('howToStart')}</button><span class="market-location">${icon('pin')}${t('malaysia')}</span><label class="language-control">${icon('globe')}<select id="language" aria-label="Language / 语言 / Bahasa"><option value="zh" ${state.lang==='zh'?'selected':''}>简体中文</option><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="ms" ${state.lang==='ms'?'selected':''}>Bahasa Melayu</option></select></label><button class="avatar top-avatar" data-action="profile" aria-label="${t('profile')}">AT</button></div></header>`}
function footer(){return `<footer><strong>${icon('path')}RePath AI <span>·</span> ${t('footer')}</strong><span>${t('prototype')}</span></footer>`}
function heroArt(){const best=ranking()[0];return `<div class="hero-art" aria-hidden="true"><div class="orbit-grid"></div><svg class="orbit-svg" viewBox="0 0 520 350" preserveAspectRatio="xMidYMid meet"><defs><linearGradient id="route" x1="0" y1="1" x2="1" y2="0"><stop stop-color="#6087FF"/><stop offset=".5" stop-color="#ABC4FF"/><stop offset="1" stop-color="#A9C1FF" stop-opacity=".2"/></linearGradient></defs><ellipse cx="282" cy="212" rx="178" ry="70" fill="none" stroke="#A9C1FF" stroke-opacity=".1" transform="rotate(-24 282 212)"/><ellipse cx="282" cy="212" rx="153" ry="54" fill="none" stroke="#A9C1FF" stroke-opacity=".07" transform="rotate(-24 282 212)"/><path d="M65 240C107 249 119 171 178 190S279 283 353 221 298 119 359 95 439 95 454 57" fill="none" stroke="url(#route)" stroke-width="2" class="orbit-stroke"/><path d="M73 254C118 265 128 185 180 205S280 296 359 235 308 136 365 109 448 110 461 69" fill="none" stroke="#A9C1FF" stroke-opacity=".13" stroke-width=".7"/><circle cx="65" cy="240" r="4" fill="#D6E2FF"/><circle cx="353" cy="221" r="5" fill="#D6E2FF"/><circle cx="353" cy="221" r="10" fill="none" stroke="#D6E2FF" stroke-opacity=".22"/><circle cx="454" cy="57" r="3" fill="#D6E2FF"/><circle cx="158" cy="194" r="2" fill="#D6E2FF"/></svg><div class="map-card map-current"><span class="tiny">${t('mapNow')}</span><strong><span class="dot"></span>${t('mapCore')}</strong></div><div class="map-card map-next"><span class="tiny">${t('mapNext')}</span><strong>${esc(local(best.title))}<span class="map-score">${best.score}<small style="font-size:7px">/100</small></span></strong></div><div class="map-center">${icon('path')}</div><span class="map-star star1">✦</span><span class="map-star star2">+</span><div class="map-tag">${t('mapFuture')}</div><span class="map-foot">${t('mapCaption')}</span></div>`}
function skillChips(ids,missing=false){return ids.map(id=>`<span class="chip ${missing?'missing':''}">${!missing?icon('check'):''}${esc(skillName(id))}<small>SDG 4</small></span>`).join('')}
function roleCard(role,index){const isSaved=state.saved.includes(role.id);return `<article class="role-card ${index===0?'top':''}"><div class="card-top"><div class="role-symbol ${role.tone}">${icon(role.icon)}</div>${index===0?`<span class="role-badge">${icon('spark')}${t('recommendedTag')}</span>`:'<span></span>'}<button class="bookmark ${isSaved?'saved':''}" data-action="save" data-id="${role.id}" aria-label="${t(isSaved?'unsave':'save')}" aria-pressed="${isSaved}">${icon('bookmark')}</button></div><h3 class="role-title">${esc(local(role.title))}</h3><p class="role-en">${state.lang==='en'?`O*NET · ${role.code}`:role.en}</p><button class="role-summary" style="width:100%;text-align:left" data-action="why" data-id="${role.id}" aria-label="${t('why')} — ${esc(local(role.title))}"><span class="score-ring" style="--score:${role.score}"><strong>${role.score}</strong></span><div><span class="match-label">${t('fit')} ${icon('info')}</span><span>${t('adjacent')} · SDG ${role.sdg}</span></div></button><div class="skills-block"><p class="skills-caption">${t('reuse')}</p><div class="chips">${skillChips(role.matched.slice(0,3))||'<span class="chip missing">—</span>'}</div></div><div class="skills-block"><p class="skills-caption">${t('gap')}</p><div class="chips">${role.missing.length?skillChips(role.missing,true):`<span class="chip">${t('allCovered')}</span>`}</div></div><div class="card-bottom"><span class="period">${icon('clock')}~ ${role.weeks} ${t('weeks')}</span><button data-action="choose" data-id="${role.id}">${t('viewPath')}${icon('arrow')}</button></div></article>`}
function scenarioSelect(){return `<label class="scenario-switch">${icon('layers')}${t('scenario')}<select id="scenario" aria-label="${t('scenario')}"><option value="moderate" ${state.scenario==='moderate'?'selected':''}>${t('moderate')}</option><option value="fast" ${state.scenario==='fast'?'selected':''}>${t('fast')}</option></select></label>`}
function marketPreview(large=false){const total=market.totals[state.quarter];return `<section class="market-preview ${large?'large-market':''}"><div class="market-preview-header"><h3>${t('localMarket')}</h3><span class="source-chip">DOSM · ${market.periods[state.quarter]}</span></div><div class="market-metric"><strong>${total.toLocaleString('en-US')}</strong>${state.quarter===1?`<span class="growth">${icon('up')}7.1% <small>${t('qoq')}</small></span>`:''}</div><p class="muted-copy">${t('offerings')} · ${t('quarterly')}</p><div class="chart-bars" aria-label="Q1 2025: 263,083; Q2 2025: 281,736"><div class="chart-bar ${state.quarter===0?'new':''}" style="--height:85%"><span>Q1 2025</span></div><div class="chart-bar ${state.quarter===1?'new':''}" style="--height:91%"><span>Q2 2025</span></div></div><div class="market-preview-foot"><span>${large?`${t('fetchTime')}: ${market.retrieved}`:t('malaysia')}</span><a href="${market.url}" target="_blank" rel="noopener noreferrer">${t('source')} ${icon('external')}</a></div>${large?`<p class="fit-note">${t('marketNote')}</p><div class="segment">${market.periods.map((p,i)=>`<button class="${state.quarter===i?'active':''}" data-action="quarter" data-quarter="${i}">${p}</button>`).join('')}</div>`:''}</section>`}
function impact(){return `<section class="impact-strip"><div><h3>${t('impactTitle')}</h3><p>${t('impactDesc')}</p></div><div class="sdg-icons"><span class="sdg-square" title="SDG 4 · ${t('sdg4')}">4</span><span class="sdg-square eight" title="SDG 8 · ${t('sdg8')}">8</span><span class="sdg-square ten" title="SDG 10 · ${t('sdg10')}">10</span></div></section>`}
function explore(){const ranked=ranking();return `<div class="page-intro"><div><h2>${t('dashboardTitle')}</h2><p>${esc(state.profile.name)} · ${t('dashboardDesc')}</p></div><div class="intro-actions"><span class="demo-label">${t('demo')}</span>${button(t('profile'),'profile','small-button','edit')}</div></div>${onboardingGuide(uiContext())}<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('spark')}${t('eyebrow')}</div><h1>${t('hero1')}<br><span>${t('hero2')}</span></h1><p>${t('heroDesc')}</p><div class="hero-buttons">${button(t('explore'),'scroll-recommendations','primary-button','arrow')}${button(t('how'),'method','text-button','chevron')}</div></div>${heroArt()}</section><section class="stats-strip"><div class="stat"><span class="stat-icon">${icon('layers')}</span><div><strong>${ranked[0].matched.length}<small>/ ${ranked[0].required.length}</small></strong><p>${t('retained')}</p></div></div><div class="stat"><span class="stat-icon">${icon('compass')}</span><div><strong>03</strong><p>${t('directions')}</p></div></div><div class="stat"><span class="stat-icon">${icon('clock')}</span><div><strong>${state.profile.hours}<small>${t('hours')}</small></strong><p>${t('weekly')}</p></div></div></section><section class="audience-row"><div><h3 class="section-kicker">${t('audienceTitle')}</h3><p class="muted-copy">${t('audienceDesc')}</p></div><div class="segment" aria-label="${t('synthetic')}">${['transition','employed','returning'].map(x=>`<button class="${state.audience===x?'active':''}" data-action="audience" data-audience="${x}" aria-pressed="${state.audience===x}">${t(x)}</button>`).join('')}</div></section><section id="recommendations"><div class="section-heading"><div><h2>${t('recommended')}</h2><p>${t('recommendSub')}</p></div>${scenarioSelect()}</div>${state.scenario==='fast'?`<div class="secondary-scenario">${t('scenarioNote')}</div>`:''}<div class="cards">${ranked.map(roleCard).join('')}</div><p class="fit-note">${icon('info')}<span>${t('fitNote')}</span></p></section><section class="lower-grid"><div class="roadmap-preview"><div class="mini-eyebrow">${t('roadmapEyebrow')}</div><h2>${t('roadmapTitle')}</h2><p class="muted-copy">${t('roadmapDesc')}</p><div class="mini-steps">${['step1','step2','step3'].map((key,i)=>`<div class="mini-step"><span class="step-number">0${i+1}</span><p>${t(key)}</p><small>${i===0?'4':i===1?Math.max(8,ranked[0].hours-12):'8'} ${t('hours')}</small></div>`).join('')}</div><button class="section-link" data-action="choose" data-id="${ranked[0].id}">${t('openPathway')}${icon('arrow')}</button></div>${marketPreview()}</section>${impact()}`}
function pathway(){const role=targetRole();const completed=state.progress[role.id]||[];const studyResource=role.missing.some(x=>['data','reporting','spreadsheet'].includes(x))?resources.data:role.missing.some(x=>['planning','budgeting'].includes(x))?resources.project:null;const missing=role.missing.map(skillName).join(' · ');const steps=[{title:t('step1'),desc:t('step1Desc'),hours:4,resource:null},{title:t('step2'),desc:missing||t('allCovered'),hours:Math.max(8,role.hours-12),resource:studyResource},{title:t('step3'),desc:t('step3Desc'),hours:8,resource:null}];return `<div class="view-heading-row"><div class="view-heading"><div class="eyebrow">${t('roadmapEyebrow')}</div><h1>${t('pathTitle')}</h1><p>${t('pathSub')}</p></div><div class="intro-actions">${button(t('compare'),'compare','small-button','compare')}${button(t('export'),'export','small-button','download')}</div></div><div class="path-mode-label">${t('starterLabel')}</div><section class="white-panel"><div class="path-selector"><label>${t('target')}<select id="target-role">${ranking().map(r=>`<option value="${r.id}" ${r.id===role.id?'selected':''}>${esc(local(r.title))} · ${r.score}/100</option>`).join('')}</select></label><div class="progress-meta">${completed.length}/3 ${t('completed')}${!state.pro?`<span class="progress-lock">${icon('lock')}Pro</span>`:''}<div class="progress-track"><span style="width:${completed.length/3*100}%"></span></div></div></div><div class="path-summary"><span class="score-ring" style="--score:${role.score}"><strong>${role.score}</strong></span><div><h2>${esc(local(role.title))}</h2><p>${esc(local(role.description))}<br>~ ${role.weeks} ${t('weeks')} · ${state.profile.hours} ${t('hours')} / ${state.lang==='zh'?'周':state.lang==='en'?'week':'minggu'} · SDG ${role.sdg}</p></div></div><div class="path-steps">${steps.map((s,i)=>`<article class="path-step ${completed.includes(i)?'done':''}"><span class="step-number">${completed.includes(i)?icon('check'):'0'+(i+1)}</span><div class="path-step-body"><div class="step-header"><h3>${s.title}</h3><span class="duration">~ ${s.hours} ${t('hours')}</span></div><p>${esc(s.desc)}</p>${i===1?`<div class="chips">${skillChips(role.missing,true)}</div>`:''}<small class="resource-provider">${s.resource?`${esc(s.resource.provider)} · ${t('freeResource')}`:t('practice')} · SDG ${i===2?role.sdg:4}</small><div class="step-footer">${s.resource?`<a href="${s.resource.url}" target="_blank" rel="noopener noreferrer">${t('openResource')}${icon('external')}</a>`:'<span></span>'}${button(t(completed.includes(i)?'markUndone':'markDone'),'complete','small-button','check',`data-step="${i}"`)}</div></div></article>`).join('')}</div><div class="path-footnotes"><p>${t('learningEstimate')}</p><p>${t('sdgExplain')}</p>${sourceLink(role.source,`O*NET · ${role.code}`)}</div></section>${upgradePreview(uiContext())}${executionPanel(uiContext())}${reflectionPanel(uiContext())}${impact()}`}
function researchItems(){return evidenceSources(uiContext())}
function signals(){return evidenceSources(uiContext())}
function pricing(){const annual=state.billing==='annual';return `<div class="view-heading pricing-heading"><div class="eyebrow">${t('planEyebrow')}</div><h1>${t('planTitle')}</h1><p>${t('planDesc')}</p></div><div class="billing-switch"><div class="segment"><button data-action="billing" data-billing="monthly" class="${!annual?'active':''}">${t('monthly')}</button><button data-action="billing" data-billing="annual" class="${annual?'active':''}">${t('annual')} <span class="pro-pill">${t('save20')}</span></button></div></div>${pricingStory(uiContext())}<section class="pricing-grid"><article class="pricing-card"><div class="plan-name">${icon('leaf')}RePath Free</div><h2><sup>RM</sup>0 <small>${t('forever')}</small></h2><p>${t('freeDesc')}</p><ul>${t('freeFeatures').map(x=>`<li>${icon('check')}${esc(x)}</li>`).join('')}</ul>${button(t(!state.sessionReady?'startFree':state.pro?'backExplore':'current'),!state.sessionReady?'start-free':'back-explore','small-button',!state.sessionReady||state.pro?'arrow':'check')}</article><article class="pricing-card paid"><div class="plan-name">${icon('spark')}RePath Pro <span class="pro-pill">${t('demo')}</span></div><h2><sup>RM</sup>${annual?'15.20':'19'} <small>${t('month')}</small></h2><p>${t('paidDesc')}</p><ul>${t('proFeatures').map(x=>`<li>${icon('check')}${esc(x)}</li>`).join('')}</ul>${button(t(state.pro?'proActive':'tryPro'),'enable-pro','primary-button',state.pro?'check':'arrow')}</article></section><p class="price-note">${t('priceNote')}</p>${impact()}`}
function saved(){const savedRoles=ranking().filter(r=>state.saved.includes(r.id));return `<div class="view-heading"><div class="eyebrow">SAVED FOR YOUR NEXT CHAPTER</div><h1>${t('saved')}</h1><p>${t('recommendSub')}</p></div>${savedRoles.length?`<div class="cards">${savedRoles.map((r,i)=>roleCard(r,3)).join('')}</div><p class="fit-note">${t('fitNote')}</p>`:`<section class="empty-state">${icon('bookmark')}<h2>${t('emptySaved')}</h2><p>${t('emptySavedDesc')}</p>${button(t('backExplore'),'back-explore','primary-button','arrow')}</section>`}`}
function about(){return `<div class="view-heading"><div class="eyebrow">EXPERIENCE IS A BEGINNING.</div><h1>${t('aboutTitle')}</h1><p>${t('tagline')}</p></div><section class="white-panel about-panel"><div class="brand">${brandMark()}<span>RePath</span><span class="brand-ai">AI</span></div><h2>${t('aboutTitle')}</h2><p>${t('aboutText')}</p><p>${t('methodDesc')}</p><p>${t('onetNote')}</p><p>${t('sdgExplain')}</p>${sourceLink(market.url,'DOSM · Job Market Insights Q2 2025')}${sourceLink('https://www.onetonline.org/','O*NET OnLine')}${sourceLink('https://www.crossref.org/documentation/retrieve-metadata/rest-api/','Crossref')}${impact()}${button(t('backExplore'),'back-explore','primary-button','arrow')}</section>`}
function planKey(){return `${state.isSample?'sample':'personal'}:${state.target}`}
function isPlanReady(){return state.planReady[planKey()]===true}
function getPlan(){
  const store=state.isSample?state.demoPlans:state.executionPlans;
  const current=store[state.target];
  if(current?.schemaVersion===3&&current.roleId===state.target&&Array.isArray(current.items)&&current.items.length<=100)return current;
  const plan=buildWeeklyPlan(activeProfile(),state.target,state.scenario);store[state.target]=plan;return plan;
}
function uiContext(){return {state:{...state,profile:activeProfile(),weeklyProgress:state.isSample?state.demoWeekly:state.weeklyProgress,reflections:state.isSample?state.demoReflections:state.reflections},t,local,esc,icon,button,brandMark,skillName,profileRole,ranking,targetRole,getPlan,isPlanReady,sourceLink}}
function resetExecution(){state.executionPlans={};state.weeklyProgress={};state.reflections=[];state.planReady={};state.goalChosen=false}
function render(){
  document.documentElement.dataset.theme=state.theme;
  document.querySelector('meta[name="theme-color"]').content=state.theme==='light'?'#eef4fc':'#0c1c30';
  document.documentElement.lang={zh:'zh-CN',en:'en',ms:'ms'}[state.lang];
  document.title='RePath';
  root.className='discovery-shell';document.body.dataset.page=state.view;
  const context=uiContext();
  const screens={welcome:discoveryLanding,sample:sampleJourney,setup:profileIntake,explore:strengthReport,opportunities:careerDirections,pathway:selectedPath,pricing:compactPricing,auth:compactAuth};
  const old={signals:()=>evidenceSources(context),about};
  let content=screens[state.view]?screens[state.view](context):state.view==='saved'?careerDirections({...context,ranking:()=>ranking().filter(role=>state.saved.includes(role.id))}):state.view==='signals'?evidenceSources(context):`<main class="d-page d-legacy">${(old[state.view]||signals)()}</main>`;
  root.innerHTML=discoveryHeader(context)+discoveryProgress(context)+`<div class="d-view view-enter">${content}</div>`+discoveryFooter(context);
  persist();
}

let previousFocus;
let pendingRecordImport=null;
function showModal(content,wide=false){previousFocus=document.activeElement;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="modal-close" data-action="close" aria-label="${t('close')}">${icon('close')}</button>${content}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>modalRoot.querySelector('input,select,button')?.focus())}
function closeModal(){pendingRecordImport=null;if(!modalRoot.innerHTML)return;modalRoot.innerHTML='';document.body.style.overflow='';previousFocus?.focus()}
function profileModal(){showModal(`<div class="eyebrow" style="color:#6087FF">YOUR EXPERIENCE MATTERS</div><h2 id="dialog-title">${t('editTitle')}</h2><p>${t('editDesc')}</p><form id="profile-form"><div class="form-grid"><label class="field">${t('displayName')}<input name="name" maxlength="40" value="${esc(state.profile.name)}" required></label><label class="field">${t('experience')}<input type="number" min="0" max="45" name="years" value="${state.profile.years}" required></label><label class="field full">${t('previousRole')}<input name="role" maxlength="100" value="${esc(profileRole())}" required></label><label class="field">${t('hoursLabel')}<input type="number" min="1" max="40" name="hours" value="${state.profile.hours}" required></label><label class="field">${t('budget')}<select name="budget"><option value="free" ${state.profile.budget==='free'?'selected':''}>${t('freeOnly')}</option><option value="low" ${state.profile.budget==='low'?'selected':''}>${t('lowCost')}</option></select></label></div><label class="field">${t('skillsLabel')}</label><div class="skills-select">${Object.keys(skills).map(id=>`<label class="skill-toggle"><input type="checkbox" name="skills" value="${id}" ${state.profile.skills.includes(id)?'checked':''}>${icon('check')}${esc(skillName(id))}</label>`).join('')}</div><p class="footnote">${t('profileSkillNote')}</p><div class="form-actions"><button type="button" class="text-button" style="margin-right:auto" data-action="reset">${t('reset')}</button><button type="button" class="small-button" data-action="close">${t('cancel')}</button><button type="submit" class="primary-button">${t('apply')}${icon('arrow')}</button></div></form>`)}
function methodModal(id){const role=id?ranking().find(r=>r.id===id):null;const timeKnown=role?.hasTimeEstimate!==false;const components=timeKnown?[['skillFit',35/75,role?.skill],['transferFit',25/75,role?.transfer],['learningFit',15/75,role?.feasibility]]:[['skillFit',35/60,role?.skill],['transferFit',25/60,role?.transfer]];showModal(`<div class="eyebrow" style="color:#6087FF">EXPLAINABLE BY DESIGN</div><h2 id="dialog-title">${role?esc(local(role.title)):t('methodTitle')}</h2><p>${t('methodDesc')}</p><div class="method-bars">${components.map(([key,weight,value])=>`<div class="method-bar"><header><span>${t(key)}</span><span>${role?`${Math.round(value*100)}/100 · `:''}${(weight*100).toFixed(1)}%</span></header><div class="method-track"><span style="width:${role?Math.round(value*100):weight*100}%"></span></div></div>`).join('')}</div>${role?`<p><strong style="color:#4F6FC0">${t('fit')}: ${role.score}/100</strong></p><p>${t('reuse')}: ${role.retained.map(skillName).map(esc).join(' · ')||'—'}</p><p>${t('gap')}: ${role.missing.map(skillName).map(esc).join(' · ')||t('allCovered')}</p>`:''}<p class="footnote">${t('fitSortNote')}</p><p class="footnote">${t('onetNote')}</p>${state.scenario==='fast'?`<p class="footnote">${t('scenarioNote')}${role?` (${role.scenarioAdjustment})`:''}</p>`:''}<div class="modal-source"><span>${t('synthetic')}</span>${sourceLink(role?.source||'https://www.onetcenter.org/database.html',role?`O*NET · ${role.code}`:'O*NET')}</div>`)}
function compareModal(){if(!state.pro){navigate('pricing');return}const ranked=ranking();showModal(`<div class="eyebrow" style="color:#6087FF">REPATH PRO · DEMO</div><h2 id="dialog-title">${t('compare')}</h2><p>${t('fitNote')}</p><div class="compare-scroll"><table class="compare-table"><thead><tr><th></th>${ranked.map(r=>`<th>${esc(local(r.title))}</th>`).join('')}</tr></thead><tbody>${[['fit',r=>`${r.score}/100`],['reuse',r=>r.matched.map(skillName).map(esc).join(' · ')||'—'],['gap',r=>r.missing.map(skillName).map(esc).join(' · ')||t('allCovered')],['estimated',r=>`~ ${r.weeks} ${t('weeks')}`]].map(([key,value])=>`<tr><td>${t(key)}</td>${ranked.map(r=>`<td>${value(r)}</td>`).join('')}</tr>`).join('')}<tr><td>SDG</td>${ranked.map(r=>`<td>${r.sdg} · ${t('sdg'+r.sdg)}</td>`).join('')}</tr><tr><td></td>${ranked.map(r=>`<td>${button(t('viewPath'),'choose','primary-button','arrow',`data-id="${r.id}"`)}</td>`).join('')}</tr></tbody></table></div>`,true)}
function exportPlan(){if(!state.pro){navigate('pricing');return}const profile=activeProfile();const r=targetRole();const plan=getPlan();const strategy=transitionStrategy(profile);const weekLines=plan.items.map(item=>`${t('weekLabel').replace('{n}',item.week)} · ${item.hours} ${t('hours')} · ${((state.isSample?state.demoWeekly:state.weeklyProgress)[r.id]||[]).includes(item.id)?t('completed'):t('practice')} · ${item.skillId?skillName(item.skillId):t({applications:'weekApplications',story:'weekStory',project:'weekProject',review:'weekReview',sprint:'weekSprint'}[item.stage]||'step2')}`).join('\n');const text=`RePath AI — ${t('footer')}\n${t('synthetic')}\n\n${profile.name} · ${profileRole()}\n${profile.years} ${t('years')} · ${profile.hours} ${t('hoursLabel')}\n\n${t('target')}: ${local(r.title)}\n${t('fit')}: ${r.score}/100\n${t('reuse')}: ${r.matched.map(skillName).join(', ')}\n${t('gap')}: ${r.missing.map(skillName).join(', ')||t('allCovered')}\n${t('estimated')}: ~${r.weeks} ${t('weeks')}\n\n1. ${t('step1')} — 4 ${t('hours')}\n${t('step1Desc')}\n2. ${t('step2')} — ${Math.max(8,r.hours-12)} ${t('hours')}\n${r.missing.some(x=>['data','reporting','spreadsheet'].includes(x))?resources.data.url:r.missing.some(x=>['planning','budgeting'].includes(x))?resources.project.url:t('practice')}\n3. ${t('step3')} — 8 ${t('hours')}\n${t('step3Desc')}\n\n${t('projectName')}: ${profile.project.name}\n${profile.project.actions}\n${profile.project.result}\n\n${local(strategy.title)}\n${local(strategy.description)}\n${local(strategy.actions).join('\n')}\n\n${t('weeklyLabel')}\n${weekLines}\n\n${t('selfReportNote')}\n${t('learningEstimate')}\n${t('fitNote')}\n${t('onetNote')}\n${t('sdgExplain')}\n${r.source}\n${market.url}\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`RePath-${r.id}-action-plan.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(t('exported'))}
async function refreshResearch(){if(state.refreshing)return;state.refreshing=true;state.researchError=false;render();state.research=await fetchArxivSnapshot(state.research);state.researchError=state.research.status==='unavailable'||state.research.status==='stale';write('repath-v02-arxiv',state.research);state.refreshing=false;render()}
async function loadResearch(){const cached=read('repath-v02-arxiv',null);try{const response=await fetch('research-cache.json');const bundled=response.ok?await response.json():null;state.research=cached&&(!bundled||cached.last_attempt_at>bundled.last_attempt_at)?cached:bundled;if(state.view==='signals')render()}catch{state.research=cached;state.researchError=!cached;if(state.view==='signals')render()}}


function enablePro(){
  state.pro=true;persist();
  if(!state.goalChosen){navigate('opportunities');toast(t('proEnabled'));return}
  if(!isPlanReady()){navigate('pathway');return}
  getPlan();navigate('pathway');toast(t('proEnabled'));
  requestAnimationFrame(()=>document.querySelector('#execution')?.scrollIntoView({block:'start'}));
}
function handleDiscoveryAction(el){
  const {action}=el.dataset;
  if(action==='records'){pendingRecordImport=null;showModal(recordsDialog(uiContext(),state));return true}
  if(action==='records-export'){exportRecords();return true}
  if(action==='records-import'){modalRoot.querySelector('#records-file')?.click();return true}
  if(action==='records-delete'){pendingRecordImport=null;showModal(recordDeleteDialog(uiContext()));return true}
  if(action==='records-confirm-import'){if(pendingRecordImport)applyRecordData(pendingRecordImport.data);return true}
  if(action==='records-confirm-delete'){applyRecordData(blankRecordData(),true);return true}

  if(action==='toggle-theme'){state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;document.querySelector('meta[name="theme-color"]').content=state.theme==='light'?'#eef4fc':'#0c1c30';const label=t(state.theme==='dark'?'themeToLight':'themeToDark');el.setAttribute('aria-label',label);el.title=label;el.innerHTML=icon(state.theme==='dark'?'sun':'moon')+'<span>'+t(state.theme==='dark'?'themeLight':'themeDark')+'</span>';persist();return true}
  if(action==='direction-family'){state.directionFamily=el.dataset.family;state.directionPage=0;state.directionFocus=null;render();return true}
  if(action==='reset-direction-filter'){state.directionFamily='all';state.directionPage=0;render();return true}
  if(action==='direction-page'){state.directionPage=Math.max(0,Number(el.dataset.page)||0);state.directionFocus=null;render();return true}
  if(action==='inspect-direction'){state.directionFocus=el.dataset.id;render();return true}
  if(action==='role-evidence'){const role=ranking().find(r=>r.id===el.dataset.id);if(role)showModal(roleEvidenceDialog(uiContext(),role));return true}
  if(action==='dosm-evidence'){showModal(dosmDialog(uiContext()),true);return true}
  if(action==='show-sample'){
    state.isSample=true;state.audience=el.dataset.audience||'transition';state.demoProfile=cleanProfile(presets[state.audience]);state.demoProfile.experience=t('experienceSeed');state.demoPlans={};state.demoWeekly={};state.demoReflections=[];state.target=ranking()[0].id;state.goalChosen=false;navigate('sample');return true;
  }
  if(action==='next-sample'){
    const order=['transition','employed','returning'];state.audience=order[(order.indexOf(state.audience)+1)%order.length];state.demoProfile=cleanProfile(presets[state.audience]);state.demoPlans={};state.demoWeekly={};state.demoReflections=[];state.target=ranking()[0].id;state.goalChosen=false;render();return true;
  }
  if(action==='start-profile'){state.isSample=false;state.setupStep=0;navigate('setup');return true}
  if(action==='my-experience'){state.isSample=false;if(state.profileConfirmed&&state.profile.project.name){navigate('explore')}else{state.setupStep=0;navigate('setup')}return true}
  if(action==='start-free'){state.pro=false;if(state.sessionReady||state.profileConfirmed){navigate('opportunities')}else{state.isSample=false;state.setupStep=0;navigate('setup')}return true}
  if(action==='open-directions'){navigate('opportunities');return true}
  if(action==='intake-back'){state.setupStep=Math.max(0,state.setupStep-1);render();return true}
  if(action==='fill-experience'){
    state.profile=cleanProfile({...presets.transition,name:state.profile.name,experience:t('experienceSeed'),project:{name:t('projectSeedName'),actions:t('experienceSeed'),result:t('projectSeedResult')}});state.profileConfirmed=true;render();return true;
  }
  if(action==='plan-hours'){
    activeProfile().hours=Math.max(1,Math.min(40,Number(el.dataset.hours)||6));render();return true;
  }
  if(action==='build-plan'){
    activeProfile().hoursConfirmed=true;const plans=state.isSample?state.demoPlans:state.executionPlans;delete plans[state.target];
    state.planReady[planKey()]=true;getPlan();render();window.scrollTo(0,0);return true;
  }
  if(action==='adjust-time'){state.planReady[planKey()]=false;render();window.scrollTo(0,0);return true}
  if(action==='toggle-navigation'){
    const nav=document.querySelector('.d-navigation');const expanded=nav.classList.toggle('open');el.setAttribute('aria-expanded',String(expanded));return true;
  }
  return false;
}
root.addEventListener('submit',e=>{
  if(e.target.id!=='discovery-intake-form')return;
  e.preventDefault();const data=new FormData(e.target);
  if(state.setupStep===0){
    const project={name:String(data.get('projectName')||'').trim(),actions:String(data.get('actions')||'').trim(),result:String(data.get('result')||'').trim()};
    state.profile=cleanProfile({...state.profile,role:String(data.get('role')||'').trim(),years:data.get('years'),project,experience:project.actions,hoursConfirmed:false});
    if(!state.profile.role||!project.name||!project.actions){toast(t('projectRequired'));return}
    state.profile.skills=suggestSkills(project.actions+' '+project.result).filter(id=>id!=='ai');
    state.setupStep=1;state.profileConfirmed=true;render();window.scrollTo(0,0);return;
  }
  if(state.setupStep===1){
    state.profile=cleanProfile({...state.profile,context:{employment:data.get('employment'),reason:data.get('reason'),priority:data.get('priority'),goal:data.get('goal'),concern:data.get('concern')}});
    state.setupStep=2;render();window.scrollTo(0,0);return;
  }
  const selected=data.getAll('skills');if(!selected.length){toast(t('setupSkillsHint'));return}
  state.profile=cleanProfile({...state.profile,skills:selected,aiUsage:Object.fromEntries(['content','analysis','coding','workflow'].map(id=>[id,data.get('ai-'+id)])),aiFocus:data.get('aiFocus')});state.profile.hoursConfirmed=false;state.isSample=false;state.sessionReady=true;state.profileConfirmed=true;resetExecution();state.target=ranking()[0].id;navigate('opportunities');
});

function handleJourneyClick(el){
  const {action,id}=el.dataset;
  if(handleDiscoveryAction(el))return true;
  if(action==='start-free'){state.pro=false;state.startDestination='explore';state.authMode='signup';navigate('auth');return true}
  if(action==='intro-home'){state.welcomeStep=0;navigate('welcome');return true}
  if(action==='intro-next'){state.welcomeStep=Math.min(2,state.welcomeStep+1);render();window.scrollTo(0,0);return true}
  if(action==='intro-back'){state.welcomeStep=Math.max(0,state.welcomeStep-1);render();window.scrollTo(0,0);return true}
  if(action==='intro-goto'){state.welcomeStep=Math.max(0,Math.min(2,Number(el.dataset.step)));render();window.scrollTo(0,0);return true}
  if(action==='auth-login'||action==='auth-start'){state.authMode=action==='auth-start'?'signup':'signin';state.onboardingComplete=true;navigate('auth');return true}
  if(action==='auth-mode'){state.authMode=el.dataset.mode==='signup'?'signup':'signin';render();return true}
  if(action==='guest-example'){state.sessionReady=true;state.onboardingComplete=true;state.pro=false;state.profile=cleanProfile(presets[state.audience]);resetExecution();state.target=ranking()[0].id;navigate('explore');return true}
  if(action==='entry-audience'){state.audience=el.dataset.audience;const name=state.profile.name;state.profile=cleanProfile(presets[state.audience]);state.profile.name=name;resetExecution();state.target=ranking()[0].id;render();return true}
  if(action==='setup-back'){if(state.setupStep===0)navigate('auth');else{state.setupStep--;render();window.scrollTo(0,0)}return true}
  if(action==='scroll-execution'){document.querySelector('#execution')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});return true}
  if(action==='weekly-complete'){
    if(!state.pro){enablePro();return true}
    const week=el.dataset.week;const plan=getPlan();if(!plan.items.some(x=>x.id===week))return true;
    const progress=state.isSample?state.demoWeekly:state.weeklyProgress;const completed=progress[plan.roleId]||[];
    progress[plan.roleId]=completed.includes(week)?completed.filter(x=>x!==week):[...completed,week];
    const position=scrollY;render();window.scrollTo(0,position);return true;
  }
  if(action==='reflect-skill'){
    if(!state.pro||!targetRole().missing.includes(id))return true;
    showModal(`<div class="eyebrow" style="color:#6087FF">LEARN. REFLECT. REPATH.</div><h2 id="dialog-title">${esc(skillName(id))}</h2><p>${esc(local(learningExercises[id]))}</p><p>${t('selfReportNote')}</p><form id="reflection-form" data-skill="${id}"><label class="reflection-consent"><input type="checkbox" required>${t('confirmSkill')}</label><div class="form-actions"><button type="button" class="small-button" data-action="close">${t('cancel')}</button><button type="submit" class="primary-button">${t('apply')}${icon('arrow')}</button></div></form>`);return true;
  }
  return false;
}
root.addEventListener('submit',e=>{
  if(e.target.id==='account-form'){
    e.preventDefault();const data=new FormData(e.target);state.profile.name=String(data.get('nickname')||'Alex Tan').trim().slice(0,40)||'Alex Tan';state.isSample=false;state.setupStep=0;navigate('setup');return;
  }
  if(e.target.id==='setup-form'){
    e.preventDefault();const data=new FormData(e.target);
    if(state.setupStep===0){state.profile=cleanProfile({...state.profile,role:data.get('role'),years:data.get('years')});}
    if(state.setupStep===1){state.profile.skills=data.getAll('skills');if(!state.profile.skills.length){toast(t('setupSkillsHint'));return}}
    if(state.setupStep===2){state.profile=cleanProfile({...state.profile,hours:data.get('hours'),budget:data.get('budget')});state.sessionReady=true;state.onboardingComplete=true;resetExecution();state.target=ranking()[0].id;navigate(state.startDestination);return}
    state.setupStep++;render();window.scrollTo(0,0);
  }
});
root.addEventListener('input',e=>{
  if(e.target.id==='setup-hours')document.querySelector('#hours-display').textContent=e.target.value;
  if(e.target.closest('#setup-form')&&e.target.name==='skills'){
    const selected=[...document.querySelectorAll('#setup-form input[name="skills"]:checked')].length;
    document.querySelector('#skill-count').textContent=selected;
  }
});
modalRoot.addEventListener('submit',e=>{
  if(e.target.id!=='reflection-form')return;
  e.preventDefault();if(!state.pro)return;
  const result=reflectSkill(activeProfile(),e.target.dataset.skill,state.target,state.scenario);
  if(state.isSample){state.demoProfile=result.profile;if(result.reflection)state.demoReflections.push(result.reflection)}else{state.profile=result.profile;if(result.reflection)state.reflections.push(result.reflection)}
  closeModal();render();toast(t('reflectionSaved'));
  requestAnimationFrame(()=>document.querySelector('.reflection-panel')?.scrollIntoView({block:'start'}));
});

function handleClick(e){if(e.target.closest('a'))return;const el=e.target.closest('[data-action],[data-view]');if(!el)return;if(el.dataset.view){navigate(el.dataset.view);return}const {action,id}=el.dataset;if(handleJourneyClick(el))return;if(action==='menu'){document.querySelector('.sidebar')?.classList.toggle('open');document.querySelector('.mobile-overlay')?.classList.toggle('open');return}if(action==='close'){closeModal();return}if(action==='profile'){profileModal();return}if(action==='method'||action==='why'){methodModal(id);return}if(action==='scroll-recommendations'){document.querySelector('#recommendations')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});return}if(action==='choose'){state.target=id;state.goalChosen=true;navigate('pathway');return}if(action==='pricing'){navigate('pricing');return}if(action==='back-explore'){navigate(state.sessionReady?'explore':'auth');return}if(action==='audience'){state.audience=el.dataset.audience;state.profile=cleanProfile(presets[state.audience]);state.progress={};resetExecution();state.target=ranking()[0].id;render();return}if(action==='reset'){state.profile=cleanProfile(presets[state.audience]);resetExecution();closeModal();render();profileModal();return}if(action==='save'){const exists=state.saved.includes(id);state.saved=exists?state.saved.filter(x=>x!==id):[...state.saved,id];render();toast(t(exists?'unsavedToast':'savedToast'));return}if(action==='quarter'){state.quarter=Number(el.dataset.quarter);render();return}if(action==='refresh'){refreshResearch();return}if(action==='billing'){state.billing=el.dataset.billing;render();return}if(action==='enable-pro'){enablePro();return}if(action==='compare'){compareModal();return}if(action==='export'){exportPlan();return}if(action==='complete'){const step=Number(el.dataset.step);const done=state.progress[state.target]||[];state.progress[state.target]=done.includes(step)?done.filter(x=>x!==step):[...done,step];render();return}}
function recordError(key){const area=modalRoot.querySelector('#records-error');if(area)area.textContent=t(key);else toast(t(key))}
function exportRecords(){
  try{const backup=createRecordBackup(state);const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='RePath-records-'+backup.exportedAt.replace(/[:.]/g,'-')+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(t('recordExported'))}catch{recordError('recordStorageError')}
}
function applyRecordData(data,deletion=false){
  const reset={audience:'transition',isSample:deletion||!data.profileConfirmed,demoProfile:cleanProfile(presets.transition),demoPlans:{},demoWeekly:{},demoReflections:[],setupStep:0,directionFamily:'all',directionSort:'fit',directionPage:0,directionFocus:null};
  try{localStorage.setItem(RECORD_STORAGE_KEY,JSON.stringify({...recordStateSnapshot(),...data,audience:reset.audience,isSample:reset.isSample,demoProfile:reset.demoProfile}))}catch{recordError('recordStorageError');return}
  Object.assign(state,data,reset);navigate(deletion||!data.profileConfirmed?'welcome':'explore');toast(t(deletion?'recordDeleted':'recordImported'));
}
modalRoot.addEventListener('change',async event=>{
  const input=event.target;if(input.id!=='records-file')return;const file=input.files?.[0];if(!file)return;
  const error=modalRoot.querySelector('#records-error');if(error)error.textContent='';
  if(file.size>RECORD_FILE_LIMIT){recordError('recordTooLarge');input.value='';return}
  try{const backup=parseRecordBackup(await file.text());if(modalRoot.querySelector('#records-file')!==input)return;pendingRecordImport=backup;showModal(recordImportDialog(uiContext(),backup,file.name))}catch{if(modalRoot.querySelector('#records-file')===input)recordError('recordInvalid')}finally{input.value=''}
});
root.addEventListener('click',handleClick);modalRoot.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();else handleClick(e)});
root.addEventListener('change',e=>{if(e.target.id==='direction-sort'){state.directionSort=e.target.value;state.directionPage=0;state.directionFocus=null;render()}if(e.target.id==='language'){state.lang=e.target.value;render()}if(e.target.id==='scenario'){state.scenario=e.target.value;render()}if(e.target.id==='target-role'){state.target=e.target.value;render()}});
modalRoot.addEventListener('submit',e=>{if(e.target.id!=='profile-form')return;e.preventDefault();const form=new FormData(e.target);state.profile=cleanProfile({name:form.get('name'),role:form.get('role'),years:form.get('years'),hours:form.get('hours'),budget:form.get('budget'),skills:form.getAll('skills')});state.progress={};resetExecution();state.target=ranking()[0].id;closeModal();render();toast(t('profileUpdated'))});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(validViews.includes(view)&&state.view!==view){closeModal();state.view=view;render();window.scrollTo(0,0)}});
document.addEventListener('keydown',e=>{if(!modalRoot.innerHTML)return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const list=[...modalRoot.querySelectorAll('button,a,input,select')].filter(el=>!el.disabled);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
render();loadResearch();
